<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('User/import')}">导入用户</a>					<a href="{pigcms{:U('User/importlist')}" class="on">导入用户列表</a>                    <a href="{pigcms{:U('User/importmoney')}">客户余额导入</a>                    <a href="{pigcms{:U('User/importmoneylist')}">导入余额列表</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('User/importlist')}" method="get">							<input type="hidden" name="c" value="User"/>							<input type="hidden" name="a" value="importlist"/>							筛选: 						<!-- 	<input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype">								<option value="uid" <if condition="$_GET['searchtype'] eq 'uid'">selected="selected"</if>>用户ID</option>								<option value="nickname" <if condition="$_GET['searchtype'] eq 'nickname'">selected="selected"</if>>昵称</option>								<option value="phone" <if condition="$_GET['searchtype'] eq 'phone'">selected="selected"</if>>手机号</option>							</select> -->							<font color="#000">添加日期筛选：</font>							<input type="text" class="input-text" name="begin_time" style="width:120px;" id="d4311"  value="{pigcms{$_GET.begin_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>			   							<input type="text" class="input-text" name="end_time" style="width:120px;" id="d4311" value="{pigcms{$_GET.end_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>							<input type="submit" value="查询" class="button"/>							&nbsp;&nbsp;&nbsp;&nbsp;							总余额：{pigcms{$money_count}{pigcms{$config['Currency_txt']}							&nbsp;&nbsp;&nbsp;							总积分：{pigcms{$score_count}个  													</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<if condition="$config['open_school'] eq '1'">									<th>ID</th>									<th>姓名</th>									<th>手机号</th>									<th>身份证号</th>									<th>学工号</th>									<th>余额</th>									<th>积分</th>									<th>账号</th>									<th>添加时间</th>								<else />								<th>ID</th>								<th>姓名</th>								<th>手机号</th>								<th>通讯地址</th>								<th>商家ID</th>								<th>会员卡号</th>								<th>等级</th>								<th>QQ</th>								<th>Email</th>								<th>余额</th>								<th>{pigcms{$config['score_name']}</th>								<th>账号</th>								<th>添加时间</th>								<th>操作</th>								</if>							</tr>						</thead>						<tbody>							<if condition="is_array($userimport)">								<volist name="userimport" id="vo">									<if condition="$config['open_school'] eq '1'">										<tr>											<td>{pigcms{$vo.uid}</td>											<td>{pigcms{$vo.truename}</td>											<td>{pigcms{$vo.phone}</td>											<td>{pigcms{$vo.school_sfz}</td>											<td>{pigcms{$vo.school_no}</td>											<td>{pigcms{$vo.now_money}</td>											<td>{pigcms{$vo.score_count}</td>											<td>{pigcms{$vo.phone}</td>											<td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>										</tr>									<else />									<tr>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$vo.ppname}</td>										<td>{pigcms{$vo.telphone}</td>										<td><php>echo str_replace('|',' ',$vo['address']);</php></td>										<td>{pigcms{$vo.mer_id}</td>										<td>{pigcms{$vo.memberid}</td>										<td>{pigcms{$vo.level}</td>										<td>{pigcms{$vo.qq}</td>										<td>{pigcms{$vo.email}</td>										<td>{pigcms{$vo.money} {pigcms{$config['Currency_txt']}</td>										<td>{pigcms{$vo.integral}</td>										<td>{pigcms{$vo.useraccount}</td>										<td>{pigcms{$vo.addtime|date='Y-m-d H:i:s',###}</td>										<td class="textcenter"><a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('User/delimportuser')}">删除</a></td>									</tr>									</if>								</volist>								<tr><td class="textcenter pagebar" colspan="14">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="14">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>